package got.wildlife; import got.GOTItems; import net.minecraft.server.level.ServerLevel; import net.minecraft.world.damagesource.DamageSource; import net.minecraft.world.entity.*; import net.minecraft.world.entity.ai.attributes.*; import net.minecraft.world.entity.ai.goal.*; import net.minecraft.world.entity.ai.goal.target.*; import net.minecraft.world.entity.animal.Animal; import net.minecraft.world.entity.player.Player; import net.minecraft.world.item.ItemStack; import net.minecraft.world.item.Items; import net.minecraft.world.level.Level; import org.jetbrains.annotations.Nullable;
public class GOTLionEntity extends Animal { public GOTLionEntity(EntityType<? extends Animal> t,Level l){super(t,l);xpReward=6;} public static AttributeSupplier.Builder createAttributes(){return Mob.createMobAttributes().add(Attributes.MAX_HEALTH,40).add(Attributes.MOVEMENT_SPEED,.22).add(Attributes.ATTACK_DAMAGE,4).add(Attributes.FOLLOW_RANGE,28);} @Override protected void registerGoals(){goalSelector.addGoal(0,new FloatGoal(this));goalSelector.addGoal(1,new MeleeAttackGoal(this,1.35,true));goalSelector.addGoal(3,new BreedGoal(this,1));goalSelector.addGoal(5,new FollowParentGoal(this,1.1));goalSelector.addGoal(6,new WaterAvoidingRandomStrollGoal(this,1));goalSelector.addGoal(7,new LookAtPlayerGoal(this,Player.class,10));goalSelector.addGoal(8,new RandomLookAroundGoal(this));targetSelector.addGoal(1,new HurtByTargetGoal(this).setAlertOthers(GOTLionEntity.class));targetSelector.addGoal(2,new NearestAttackableTargetGoal<>(this,net.minecraft.world.entity.animal.Sheep.class,true));targetSelector.addGoal(3,new NearestAttackableTargetGoal<>(this,net.minecraft.world.entity.animal.Cow.class,true));} @Override public boolean isFood(ItemStack s){return s.is(Items.BEEF)||s.is(Items.MUTTON);} @Nullable @Override public GOTLionEntity getBreedOffspring(ServerLevel l,AgeableMob m){return (GOTLionEntity)getType().create(l);} @Override protected void dropCustomDeathLoot(DamageSource s,int looting,boolean hit){super.dropCustomDeathLoot(s,looting,hit);for(int i=0;i<1+random.nextInt(2)+random.nextInt(looting+1);i++)spawnAtLocation(GOTItems.FUR.get());for(int i=0;i<1+random.nextInt(3)+random.nextInt(looting+1);i++)spawnAtLocation(isOnFire()?GOTItems.LION_COOKED.get():GOTItems.LION_RAW.get());} }